import os

os.makedirs("system", exist_ok=True)
os.makedirs("constant", exist_ok=True)

controlDict = """FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      controlDict;
}
application     simpleFoam;
startFrom       startTime;
startTime       0;
stopAt          endTime;
endTime         1;
deltaT          1;
writeControl    timeStep;
writeInterval   1;
purgeWrite      0;
writeFormat     ascii;
writePrecision  6;
writeCompression off;
timeFormat      general;
timePrecision   6;
runTimeModifiable true;
"""
with open("system/controlDict", "w") as f:
    f.write(controlDict)

fvSchemes = """FoamFile
{
    version 2.0;
    format  ascii;
    class   dictionary;
    object  fvSchemes;
}
ddtSchemes { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes { default corrected; }
"""
with open("system/fvSchemes", "w") as f:
    f.write(fvSchemes)

fvSolution = """FoamFile
{
    version 2.0;
    format  ascii;
    class   dictionary;
    object  fvSolution;
}
solvers {}
"""
with open("system/fvSolution", "w") as f:
    f.write(fvSolution)

print("minimal case files written")
print(os.listdir("system"))

